import { gsap } from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'

let scrollTriggerRegistered = false

export const getGsap = () => gsap

const ensureMatchMedia = () => {
  if (
    typeof window === 'undefined' ||
    typeof window.matchMedia === 'function'
  ) {
    return
  }

  window.matchMedia = (query: string): MediaQueryList =>
    ({
      matches: false,
      media: query,
      onchange: null,
      addListener: () => undefined,
      removeListener: () => undefined,
      addEventListener: () => undefined,
      removeEventListener: () => undefined,
      dispatchEvent: () => false,
    }) as MediaQueryList
}

export const registerScrollTrigger = () => {
  if (scrollTriggerRegistered) return ScrollTrigger

  ensureMatchMedia()
  gsap.registerPlugin(ScrollTrigger)
  scrollTriggerRegistered = true
  return ScrollTrigger
}

export const isScrollTriggerRegistered = () => scrollTriggerRegistered

export const refreshScrollTriggers = () => {
  if (!scrollTriggerRegistered) return
  ScrollTrigger.refresh()
}

export const killScrollTriggersFor = (target: Element) => {
  if (!scrollTriggerRegistered) return

  for (const trigger of ScrollTrigger.getAll()) {
    if (trigger.trigger === target) {
      trigger.kill()
    }
  }
}

import { getCurrentScope, onScopeDispose } from 'vue'
import {
  getGsap,
  killScrollTriggersFor,
  refreshScrollTriggers,
  registerScrollTrigger,
} from '../gsap/register'
import {
  getGsapPresetVars,
  resolveMotionTarget,
  sanitizeGsapVars,
} from '../gsap/resolve'
import { isMotionReducedOrDisabled } from '../runtime'
import type { MotionTarget } from '../gsap/resolve'
import type { MotionPresetInput, MotionPresetName } from '../types'

export type ScrollRevealOptions = {
  target?: MotionTarget
  name?: MotionPresetInput
  duration?: string | number
  disabled?: boolean
  once?: boolean
  start?: string
  end?: string
  markers?: boolean
  scrub?: boolean | number
  scroller?: Element | Window | string
  vars?: gsap.TweenVars
  scrollTrigger?: ScrollTrigger.StaticVars
}

export type ScrollRevealRunOptions = Omit<ScrollRevealOptions, 'target'>

const defaultScrollRevealPreset: MotionPresetName = 'paper-settle'

const applyReducedState = (
  target: ReturnType<typeof resolveMotionTarget>,
  vars: gsap.TweenVars,
  fallback: (target: gsap.TweenTarget, vars: gsap.TweenVars) => void,
) => {
  if (target instanceof Element && 'style' in target) {
    const element = target as HTMLElement | SVGElement
    if (vars.opacity !== undefined) element.style.opacity = String(vars.opacity)
    if (typeof vars.transform === 'string')
      element.style.transform = vars.transform
    if (typeof vars.filter === 'string') element.style.filter = vars.filter
    return
  }

  fallback(target as gsap.TweenTarget, vars)
}

export const useScrollReveal = (defaults: ScrollRevealOptions = {}) => {
  const gsap = getGsap()
  const tweens = new Set<gsap.core.Tween>()

  const reveal = (
    target: MotionTarget = defaults.target,
    overrides: ScrollRevealRunOptions = {},
  ) => {
    const options = {
      ...defaults,
      ...overrides,
    }
    const resolvedTarget = resolveMotionTarget(target)
    if (!resolvedTarget) return undefined

    const preset = getGsapPresetVars(
      options.name || defaultScrollRevealPreset,
      options.duration,
    )
    const finalVars = {
      ...sanitizeGsapVars(preset.to),
      ...options.vars,
    }

    if (isMotionReducedOrDisabled(options.disabled)) {
      applyReducedState(resolvedTarget, finalVars, gsap.set)
      return undefined
    }

    registerScrollTrigger()

    const trigger = options.scrollTrigger?.trigger || resolvedTarget
    const tween = gsap.fromTo(resolvedTarget, sanitizeGsapVars(preset.from), {
      ...finalVars,
      duration: preset.duration,
      ease: preset.ease,
      scrollTrigger: {
        trigger,
        start: options.start || 'top 85%',
        end: options.end,
        once: options.once ?? true,
        markers: options.markers,
        scrub: options.scrub,
        scroller: options.scroller,
        toggleActions:
          (options.once ?? true)
            ? 'play none none none'
            : 'play reverse play reverse',
        ...options.scrollTrigger,
      },
    })

    tweens.add(tween)
    return tween
  }

  const kill = () => {
    for (const tween of tweens) {
      tween.scrollTrigger?.kill()
      tween.kill()
    }
    tweens.clear()

    const target = resolveMotionTarget(defaults.target)
    if (target instanceof Element) {
      killScrollTriggersFor(target)
    }
  }

  const controls = {
    reveal,
    kill,
    refresh: refreshScrollTriggers,
    tweens,
  }

  if (getCurrentScope()) {
    onScopeDispose(kill)
  }

  return controls
}

export default useScrollReveal

import { getCurrentScope, onScopeDispose, unref } from 'vue'
import { getGsap } from '../gsap/register'
import type { Ref } from 'vue'

export type GsapScope =
  | Element
  | Ref<Element | undefined | null>
  | undefined
  | null

type GsapInstance = ReturnType<typeof getGsap>

export type GsapContextCallback = Parameters<GsapInstance['context']>[0]

export const useGsapContext = (scope?: GsapScope) => {
  const contexts = new Set<gsap.Context>()
  const gsap = getGsap()

  const resolveScope = () => unref(scope) || undefined

  const create = (callback?: GsapContextCallback) => {
    const context = gsap.context(callback || (() => undefined), resolveScope())
    contexts.add(context)
    return context
  }

  const revert = () => {
    for (const context of contexts) {
      context.revert()
    }
    contexts.clear()
  }

  if (getCurrentScope()) {
    onScopeDispose(revert)
  }

  return {
    create,
    revert,
    contexts,
  }
}

import { getCurrentScope, onScopeDispose } from 'vue'
import {
  getGsap,
  refreshScrollTriggers,
  registerScrollTrigger,
} from '../gsap/register'
import {
  getGsapPresetVars,
  resolveMotionTarget,
  sanitizeGsapVars,
  toGsapScrubSeconds,
} from '../gsap/resolve'
import { normalizeMotionRecipeOptions } from '../recipes'
import { isMotionReducedOrDisabled } from '../runtime'
import type { MotionTarget } from '../gsap/resolve'
import type { MotionRecipeName } from '../types'

export type ScrollTimelineSegment = {
  target?: MotionTarget
  from: number
  to: number
  recipe?: MotionRecipeName
  duration?: string | number
  vars?: gsap.TweenVars
  fromVars?: gsap.TweenVars
  toVars?: gsap.TweenVars
}

export type UseScrollTimelineOptions = {
  target?: MotionTarget
  segments?: ScrollTimelineSegment[]
  disabled?: boolean
  once?: boolean
  start?: string
  end?: string
  // Scrub smoothing: boolean for on/off, number/string for smoothing in
  // seconds. Strings may carry an 'ms'/'s' suffix and are normalized via
  // toGsapScrubSeconds.
  scrub?: boolean | number | string
  scroller?: Element | Window | string
  markers?: boolean
  mode?: 'natural'
  reducedFallback?: 'terminal'
  // Caller-supplied ScrollTrigger overrides. `pin` and `snap` are passed
  // through to gsap verbatim when provided; the safe defaults (pin: false,
  // snap: undefined) only apply when the caller omits them.
  scrollTrigger?: ScrollTrigger.StaticVars
}

const clampProgress = (value: number) => Math.min(Math.max(value, 0), 1)

export const useScrollTimeline = (defaults: UseScrollTimelineOptions = {}) => {
  const gsap = getGsap()
  const timelines = new Set<gsap.core.Timeline>()

  const create = (overrides: UseScrollTimelineOptions = {}) => {
    const options = {
      ...defaults,
      ...overrides,
      segments: overrides.segments ?? defaults.segments ?? [],
    }
    const trigger = resolveMotionTarget(options.target)
    if (!trigger) return undefined

    const resolvedSegments = options.segments
      .map((segment) => ({
        ...segment,
        from: clampProgress(segment.from),
        to: clampProgress(segment.to),
      }))
      .filter((segment) => segment.to >= segment.from)

    if (resolvedSegments.length === 0) return undefined

    if (isMotionReducedOrDisabled(options.disabled)) {
      for (const segment of resolvedSegments) {
        const target = resolveMotionTarget(segment.target ?? options.target)
        if (!target) continue
        const recipeOptions = normalizeMotionRecipeOptions(
          segment.recipe ?? 'content-enter',
        )
        const preset = getGsapPresetVars(
          recipeOptions.name,
          segment.duration ?? recipeOptions.duration,
        )
        gsap.set(target as gsap.TweenTarget, {
          ...sanitizeGsapVars(preset.to),
          ...segment.toVars,
          ...segment.vars,
        })
      }
      return undefined
    }

    registerScrollTrigger()

    // Respect caller-supplied pin/snap. The safe defaults only kick in
    // when the caller omits them; explicit values pass through.
    const callerScrollTrigger = options.scrollTrigger ?? {}
    const rest: ScrollTrigger.StaticVars = { ...callerScrollTrigger }
    delete rest.pin
    delete rest.snap
    const pin = callerScrollTrigger.pin ?? false
    const snap = callerScrollTrigger.snap

    const timeline = gsap.timeline({
      paused: false,
      scrollTrigger: {
        trigger,
        start: options.start || 'top 90%',
        end: options.end || 'bottom 10%',
        scrub: toGsapScrubSeconds(options.scrub ?? true),
        once: options.once,
        scroller: options.scroller,
        markers: options.markers,
        ...rest,
        pin,
        snap,
      },
    })

    for (const segment of resolvedSegments) {
      const target = resolveMotionTarget(segment.target ?? options.target)
      if (!target) continue

      const recipeOptions = normalizeMotionRecipeOptions(
        segment.recipe ?? 'content-enter',
      )
      const preset = getGsapPresetVars(
        recipeOptions.name,
        segment.duration ?? recipeOptions.duration,
      )

      timeline.fromTo(
        target as gsap.TweenTarget,
        {
          ...sanitizeGsapVars(preset.from),
          ...segment.fromVars,
        },
        {
          ...sanitizeGsapVars(preset.to),
          duration: Math.max(segment.to - segment.from, 0.001),
          ease: preset.ease,
          ...segment.vars,
          ...segment.toVars,
        },
        segment.from,
      )
    }

    timelines.add(timeline)
    return timeline
  }

  const kill = () => {
    for (const timeline of timelines) {
      timeline.scrollTrigger?.kill()
      timeline.kill()
    }
    timelines.clear()
  }

  const controls = {
    create,
    kill,
    refresh: refreshScrollTriggers,
    timelines,
  }

  if (getCurrentScope()) {
    onScopeDispose(kill)
  }

  return controls
}

export default useScrollTimeline

import { getCurrentScope, onScopeDispose } from 'vue'
import { getGsap } from '../gsap/register'
import {
  getGsapPresetVars,
  resolveMotionTarget,
  sanitizeGsapVars,
} from '../gsap/resolve'
import { normalizeMotionRecipeOptions } from '../recipes'
import { isMotionReducedOrDisabled } from '../runtime'
import type { MotionTarget } from '../gsap/resolve'
import type {
  MotionPresetInput,
  MotionPresetName,
  MotionRecipeName,
} from '../types'

export type MotionTimelineStep = {
  target: MotionTarget
  preset?: MotionPresetInput
  recipe?: MotionRecipeName
  duration?: string | number
  position?: gsap.Position
  from?: gsap.TweenVars
  to?: gsap.TweenVars
  vars?: gsap.TweenVars
}

export type UseTimelineOptions = {
  disabled?: boolean
  paused?: boolean
  timeline?: gsap.TimelineVars
}

const defaultTimelinePreset: MotionPresetName = 'paper-settle'

export const useTimeline = (options: UseTimelineOptions = {}) => {
  const gsap = getGsap()
  const timeline = gsap.timeline({
    paused: options.paused ?? true,
    ...options.timeline,
  })

  const add = (step: MotionTimelineStep) => {
    const target = resolveMotionTarget(step.target)
    if (!target) return controls

    const recipeOptions = step.recipe
      ? normalizeMotionRecipeOptions(step.recipe)
      : undefined
    const preset = getGsapPresetVars(
      step.preset || recipeOptions?.name || defaultTimelinePreset,
      step.duration ?? recipeOptions?.duration,
    )
    const fromVars = {
      ...sanitizeGsapVars(preset.from),
      ...step.from,
    }
    const toVars = {
      ...sanitizeGsapVars(preset.to),
      duration: preset.duration,
      ease: preset.ease,
      ...step.vars,
      ...step.to,
    }

    if (isMotionReducedOrDisabled(options.disabled)) {
      gsap.set(target, {
        ...sanitizeGsapVars(preset.to),
        ...step.to,
      })
      return controls
    }

    timeline.fromTo(target, fromVars, toVars, step.position)
    return controls
  }

  const kill = () => {
    timeline.kill()
  }

  const controls = {
    timeline,
    add,
    play: () => timeline.play(),
    pause: () => timeline.pause(),
    reverse: () => timeline.reverse(),
    restart: () => timeline.restart(),
    clear: () => {
      timeline.clear()
      return controls
    },
    kill,
  }

  if (getCurrentScope()) {
    onScopeDispose(kill)
  }

  return controls
}

export default useTimeline
